package game.agent.growth;
import game.agent.llm.Json;import game.agent.action.ActionResult;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GrowthRecoveryTest {
 private GrowthWorld forest(){GrowthWorld w=new GrowthWorld(()->0);w.starter("MUDKIP");for(int i=0;i<60&&!w.region().equals("forest");i++)w.execute("go_to_region",Json.object("regionId","forest"));assertEquals("forest",w.region());return w;}
 @Test void remoteRestRejectedWithoutHealing(){GrowthWorld w=forest();w.partner().hurt(5);int hp=w.partner().getHitPoints();assertFalse(w.canRest());assertEquals("RECOVERY_POINT_REQUIRED",w.rest().getCode());assertEquals(hp,w.partner().getHitPoints());}
 @Test void faintedPartnerWalksToCampAndRestoresWithoutRespawningOrGrantingXp(){GrowthWorld w=forest();w.partner().hurt(w.partner().maxHp());w.partner().pp.put("TACKLE",0);String encounters=Json.write(w.view().get("encounters"));int xp=w.partner().experience;for(int i=0;i<60&&!w.canRest();i++){int x=((Number)w.view().get("x")).intValue(),y=((Number)w.view().get("y")).intValue();assertNotEquals(ActionResult.Status.REJECTED,w.execute("go_to_recovery",Collections.emptyMap()).getStatus());assertTrue(Math.abs(x-((Number)w.view().get("x")).intValue())<=1);assertTrue(Math.abs(y-((Number)w.view().get("y")).intValue())<=1);}assertTrue(w.canRest());w=GrowthWorld.restore(Json.asObject(Json.read(Json.write(w.export()))),()->0);assertTrue(w.canRest());assertEquals(w.partner().maxHp(),w.partner().getHitPoints());assertEquals("GROWTH_RESTED",w.rest().getCode());assertEquals(w.partner().maxHp(),w.partner().getHitPoints());assertTrue(w.partner().pp.get("TACKLE")>0);assertEquals(xp,w.partner().experience);assertEquals(encounters,Json.write(w.view().get("encounters")));}
 @Test void aiHasRecoveryToolAndAuthoritativeLocation(){GrowthWorld w=forest();assertTrue(w.trainingTools().definitions().stream().anyMatch(d->d.getName().equals("go_to_recovery")));assertEquals("false",w.observation().get("canRest"));assertEquals("false",w.view().get("canRest").toString());}
}
